<script setup lang="ts">
import { computed,ref,onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { api,downloadFile } from '../../api/client'
import { dateInput } from '../../utils/formatDate'
import { formatMoney } from '../../utils/money'
import type { Client,Page } from '../../types'
const route=useRoute(),statement=computed(()=>route.meta.reportKind==='statement'),client=ref(''),currency=ref(''),from=ref(dateInput().slice(0,8)+'01'),to=ref(dateInput()),clients=ref<Client[]>([]),error=ref(''),busy=ref(false),report=ref<any>(null),loadedQuery=ref('')
onMounted(async()=>{try{let page=1,last=1;do{const result=await api<Page<Client>>('/clients?per_page=100&page='+page);clients.value.push(...result.data);last=result.last_page;page++}while(page<=last)}catch(e){error.value=(e as Error).message}})
function query(){const p=new URLSearchParams({to:to.value});if(statement.value)p.set('from',from.value);if(client.value)p.set('client_id',client.value);if(currency.value)p.set('currency',currency.value.toUpperCase());return '/reports/'+(statement.value?'statement':'ageing')+'?'+p}
async function load(){busy.value=true;error.value='';report.value=null;try{const path=query();report.value=await api(path);loadedQuery.value=path}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function csv(){busy.value=true;error.value='';try{await downloadFile(loadedQuery.value+'&format=csv',(statement.value?'statement':'ageing')+'-'+report.value.to+'.csv')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const buckets=[['current_minor','Not overdue'],['days_1_30_minor','1–30 days'],['days_31_60_minor','31–60 days'],['days_61_90_minor','61–90 days'],['days_over_90_minor','Over 90 days']]
</script>
<template><div class="page-heading"><div><h1>{{ statement?'Client statements':'Due & overdue invoices' }}</h1><p class="muted">{{ statement?'Invoice and recorded payment activity with opening and closing balances.':'Outstanding invoices grouped into ageing bands.' }} Currencies stay separate.</p></div></div><p v-if="error" class="error" role="alert">{{ error }}</p><section class="panel form-panel"><form class="form-grid" @submit.prevent="load"><label>Client<select v-model="client" :required="statement"><option value="">{{ statement?'Select a client':'All clients' }}</option><option v-for="c in clients" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label v-if="statement">From<input type="date" v-model="from" required></label><label>{{ statement?'To':'As of' }}<input type="date" v-model="to" :min="statement?from:undefined" required></label><label>Currency (optional)<input v-model="currency" maxlength="3" placeholder="All currencies, or USD"></label><button class="button primary" :disabled="busy">{{ busy?'Loading…':'Generate report' }}</button></form></section><template v-if="report"><section class="panel form-panel spaced"><div class="page-heading"><h2>{{ report.client?.name||'All clients' }} · {{ report.to }}</h2><button class="button secondary" :disabled="busy" @click="csv">Download CSV</button></div><div v-for="g in report.totals" :key="g.currency+g.minor_units" class="spaced"><h2>{{ g.currency }}</h2><template v-if="statement"><p>Opening: {{ formatMoney(g.opening_minor,g.currency,g.minor_units) }}</p><p>Invoiced: {{ formatMoney(g.invoiced_minor,g.currency,g.minor_units) }} · Payments: {{ formatMoney(g.paid_minor,g.currency,g.minor_units) }}</p></template><template v-else><p v-for="b in buckets" :key="b[0]">{{ b[1] }}: {{ formatMoney(g[b[0]!],g.currency,g.minor_units) }}</p></template><p><strong>{{ statement?'Closing balance':'Outstanding' }}: {{ formatMoney(g.closing_minor,g.currency,g.minor_units) }}</strong></p></div><p v-if="!report.totals.length">No issued invoices match these filters.</p><div class="table-wrap spaced"><table><thead><tr><th>Date</th><th>Document / client</th><th v-if="statement">Debit</th><th v-if="statement">Payment</th><th>{{ statement?'Running balance':'Outstanding' }}</th><th v-if="!statement">Days overdue</th></tr></thead><tbody><tr v-for="(row,n) in report.rows" :key="n"><td>{{ row.date }}</td><td>{{ row.reference }}<small>{{ row.client }} · {{ row.type }}</small></td><td v-if="statement">{{ formatMoney(row.debit_minor,row.currency,row.minor_units) }}</td><td v-if="statement">{{ formatMoney(row.credit_minor,row.currency,row.minor_units) }}</td><td>{{ formatMoney(row.balance_minor,row.currency,row.minor_units) }}</td><td v-if="!statement">{{ row.days_overdue }}</td></tr></tbody></table></div></section></template><p class="muted spaced">Based on currently retained issued invoices and recorded payments through the selected date. Draft/void invoices are excluded. Deleted payments and later voids are not reconstructed; this is an operational report, not an immutable accounting ledger. CSV amounts are integer minor units with currency and decimal precision columns.</p></template>
